-- Recorrido confirmado por el propietario: sólo contenido de la guía, sin operaciones financieras.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('cancelar-pago-anticipado-beca',$texto$Pago anticipado y cancelación: dos mensualidades, beca del 20% y beneficio del 10%$texto$,'Cobranza',$texto$Preparar dos mensualidades, validar un pago de $1,440.00 y cancelar ese mismo registro erróneo. Comprobar el regreso de $800.00 por mes, la beca conservada y la reversión bancaria con historial.$texto$,$texto$Alumno de prueba inscrito en un ciclo que cubra noviembre y diciembre de 2026; tutor responsable financiero con acceso familiar; institución, plantel y moneda compatibles. Usuario administrativo identificado y autorizado. Cuenta bancaria activa, abierta a más tardar en la fecha del pago, con fondos para compensar el ingreso al cancelar. Usar un ensayo sin dinero real y adaptar fechas a la inscripción y plazo. No repetir el caso ya terminado.$texto$,$texto$ANTICIPO-TEST-02: noviembre y diciembre originales $1,000.00 cada uno; beca $200.00 y beneficio adicional $80.00 por mes; un pago de $1,440.00 distribuido en $720.00 por mes. Validar deja deuda0 y banco B+1440; cancelar deja $800.00 por mes y banco B. Caso confirmado: acuerdo ANT-20261010-000002, pago PAG-20261009-000002. Los folios dependen de la BD; Git no transporta los registros.$texto$,1,DATE '2026-10-09','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONCEPTO_COBRO_ADMINISTRAR','BECA_ALUMNO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','CONVENIO_PAGO_ADMINISTRAR','PAGO_REGISTRAR','PAGO_LEER','PAGO_VALIDAR','PAGO_CANCELAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='cancelar-pago-anticipado-beca';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('cancelar-pago-anticipado-beca',1,$texto$Identificar la familia y anotar la cuenta inicial$texto$,$texto$Administración$texto$,$texto$Inscripciones, Tutores y Cuentas financieras$texto$,$texto$1. Entra a Operación escolar → Control escolar → Inscripciones y consulta al alumno de prueba. Comprueba institución, plantel e inscripción vigente para noviembre y diciembre de 2026; si no hay fecha final de inscripción, revisa el límite del ciclo. 2. En Tutores comprueba el vínculo financiero activo y el acceso familiar; usa una ventana privada para consultar después como tutor. 3. En Administración → Finanzas → Cuentas financieras busca la cuenta bancaria compatible y anota Saldo actual como B, no Saldo inicial. Verifica que la fecha de apertura/saldo inicial sea igual o anterior a la fecha real del pago de ensayo. 4. Anota alumno, matrícula, tutor y cuenta. Si sólo consultas el caso terminado, conserva los folios existentes y omite las nuevas capturas.$texto$,$texto$Alumno, tutor, cuenta y saldo B identificados.$texto$,$texto$Contexto preparado sin recibir dinero.$texto$,$texto$En el ensayo se detectó pago09/10/2026 y apertura10/10/2026: el sistema rechazó correctamente validar. Corrige una fecha sólo si fue capturada equivocadamente; no falsees la apertura ni la recepción para eludir la regla.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('cancelar-pago-anticipado-beca',2,$texto$Crear el concepto exclusivo del ensayo$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Conceptos de cobro y busca ANTICIPO-TEST-02. Si ya pertenece al ensayo concluido, sólo consulta; para otro ensayo usa un código nuevo. 2. Pulsa Nuevo registro y captura institución Instituto Raices, Código ANTICIPO-TEST-02, Categoría Colegiatura y Nombre Colegiatura prueba de cancelación de anticipo. 3. Captura Descripción: Ensayo de pago anticipado con beca y cancelación posterior del pago. Activa Permite beca, Permite descuento y Concepto activo; desactiva Permite recargo. 4. Pulsa Crear concepto y comprueba código y opciones; todavía no se crean adeudos ni ingresos.$texto$,$texto$Concepto de colegiatura que permite beca y descuento, sin recargo.$texto$,$texto$Concepto preparado para aislar el cálculo.$texto$,$texto$La institución y el plantel se seleccionan desde los registros disponibles; el código de ejemplo no debe duplicarse.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('cancelar-pago-anticipado-beca',3,$texto$Asignar la beca antes de generar$texto$,$texto$Administración$texto$,$texto$Becas por alumno$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Becas por alumno → Nuevo registro. Selecciona institución, plantel e inscripción vigente del alumno. 2. Selecciona un Tipo de beca activo y el concepto ANTICIPO-TEST-02; Modalidad Porcentaje y Porcentaje20. 3. Captura Inicio01/11/2026, Fin31/12/2026, Estado Activa y Motivo y autorización: Se autoriza beca del 20% para noviembre y diciembre de 2026 para probar un acuerdo anticipado y la cancelación posterior del pago. 4. Pulsa Asignar beca y comprueba que exista una sola beca compatible activa antes de emitir las mensualidades.$texto$,$texto$20% de $1,000.00 = $200.00 por mes.$texto$,$texto$Beca autorizada y banco B.$texto$,$texto$Adapta fechas a inscripción/ciclo. Una beca creada después de emitir los cargos no modifica automáticamente esos adeudos.$texto$,$texto$/admin/catalogos/becas-alumno$texto$),
('cancelar-pago-anticipado-beca',4,$texto$Configurar noviembre y diciembre$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Crear cuota. Selecciona institución, plantel, inscripción y concepto ANTICIPO-TEST-02. 2. Captura Importe individual1000.00, Moneda MXN y Motivo del importe personalizado: Importe de ensayo para cancelación de pago anticipado. 3. Elige Cada mes, Primer mes noviembre de 2026, Último mes diciembre de 2026, Día límite20, Estado Activa e Incluir en generación automática de cargos. En Configuración adicional · vigencia de la cuota verifica desde01/11/2026 hasta31/12/2026. 4. Pulsa Crear cuota, revisa alumno, importe y fechas del modal y confirma una sola vez.$texto$,$texto$Dos mensualidades originales de $1,000.00, vencimientos20/11/2026 y20/12/2026.$texto$,$texto$Calendario mensual preparado, sin ingreso.$texto$,$texto$Guardar cuota no recibe dinero. La vigencia de cuota y la fecha límite del acuerdo anticipado son decisiones distintas.$texto$,$texto$/admin/cuotas-alumno/nuevo$texto$),
('cancelar-pago-anticipado-beca',5,$texto$Generar y comprobar los dos adeudos$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos → Generar automáticos$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos; selecciona contexto y Generar hasta31/12/2026. 2. Pulsa Visualizar cuotas de alumnos por aplicar → Desmarcar todos y marca sólo noviembre y diciembre del alumno y concepto de prueba. Si diciembre ya existe, genera únicamente noviembre faltante. 3. Pulsa Confirmar y generar adeudos seleccionados, revisa y confirma el modal; vuelve al listado y busca alumno/concepto con situación Con saldo pendiente. 4. Abre Ver → Resumen de cada mes: Original1000, Beca200 y Falta por pagar800. Deben existir dos cargos y deuda total1600 antes del acuerdo.$texto$,$texto$Noviembre $800.00 + diciembre $800.00 = $1,600.00.$texto$,$texto$Dos mensualidades comprobadas, sin abonos ni recargos.$texto$,$texto$En el ensayo inicial sólo se había generado diciembre. No continúes con dos meses si sólo ves uno, ni dupliques el existente; revisa cuota y selección.$texto$,$texto$/admin/cargos/generar$texto$),
('cancelar-pago-anticipado-beca',6,$texto$Preparar y confirmar el acuerdo completo$texto$,$texto$Administración$texto$,$texto$Convenios de pago → Acuerdos por pago anticipado$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Convenios de pago → Acuerdos por pago anticipado → Nueva propuesta. Selecciona institución y tutor, busca y agrega noviembre y diciembre del concepto de ensayo; deben verse dos tarjetas. 2. Selecciona Conservar beca y agregar beneficio, Beneficio autorizado Porcentaje adicional, Valor10 y Fecha límite para pagar completo31/10/2026. Motivo: Se autoriza un beneficio adicional del 10% sobre el saldo después de la beca por pagar completas noviembre y diciembre antes del 31/10/2026, conservando la beca del 20%; ensayo de cancelación posterior por registro erróneo. 3. Pulsa Visualizar acuerdo y revisa cada fila Original1000, Beca conservada200, Otros ajustes0, Base800, Beneficio80 y Pago requerido720; totales Base1600, Beneficio160 y Pago1440. 4. Pulsa Guardar propuesta y revisa el modal; Cancelar sólo cierra sin guardar. Vuelve a guardar y confirma una sola vez; anota folio ANT y comprueba Propuesta vigente, deudas800 por mes y banco B.$texto$,$texto$Dos pagos requeridos720; una propuesta total1440.$texto$,$texto$Propuesta autorizada, todavía sin beneficio aplicado.$texto$,$texto$El 10% se calcula sobre800, no sobre1000. Ajusta el plazo si ensayas después de octubre. Si ya hay pago pendiente de una propuesta incompleta, cancela ese pago primero y luego la propuesta; conserva el historial y prepara otra con los dos meses.$texto$,$texto$/admin/convenios-pago/anticipados/nuevo$texto$),
('cancelar-pago-anticipado-beca',7,$texto$Registrar un solo pago de $1,440$texto$,$texto$Administración$texto$,$texto$Detalle del acuerdo → Registrar pago completo como pendiente$texto$,$texto$1. En Acuerdos por pago anticipado busca la propuesta correcta → Ver → Registrar pago completo como pendiente. Comprueba dos mensualidades y Total1440. 2. Selecciona Método Tarjeta, Fecha y hora del pago reales dentro del plazo y no anteriores a la apertura de la cuenta, Cuenta donde se recibió el dinero bancaria y Referencia ANTICIPO-TEST-02-1440. Tarjeta no exige archivo aquí; transferencia sí exige comprobante. 3. Pulsa Registrar pago completo, revisa el modal y confirma una sola vez. Anota el folio PAG y abre Ver pago: debe existir un único registro por1440, no dos registros720. 4. En Distribución comprueba720 para noviembre y720 para diciembre. Cada saldo actual800 muestra Beneficio al validar el pago completo80 y saldo estimado0; el beneficio está condicionado a validación, no publicado todavía.$texto$,$texto$Un pago1440 distribuye720+720; banco B hasta validar.$texto$,$texto$Pago En revisión asociado al acuerdo completo.$texto$,$texto$La referencia terminada en1440 es texto, no fija el importe. El primer intento de sólo diciembre produjo720 y se canceló estando pendiente; no uses ese folio ni dupliques el pago nuevo. Registra desde el acuerdo, no desde un formulario ordinario desvinculado.$texto$,$texto$/admin/convenios-pago/anticipados$texto$),
('cancelar-pago-anticipado-beca',8,$texto$Validar y comprobar el ingreso$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Gestión$texto$,$texto$1. Entra a Administración → Finanzas → Pagos recibidos, busca el folio nuevo por1440 → Ver → Gestión. Comprueba la cuenta bancaria destino precargada y conserva el importe sin activar recibido mayor. 2. Pulsa Validar y publicar, revisa folio, cuenta e importe del modal y confirma una sola vez. 3. Si aparece La fecha del pago es anterior a la fecha de apertura de la cuenta destino, compara ambas fechas: corrige sólo el dato equivocado desde su procedimiento y reintenta el mismo pago pendiente. Un rechazo de validación no publica el ingreso; no lo compenses con un movimiento manual. 4. Al validar comprueba Pago Validado, acuerdo Beneficio aplicado y Cuentas financieras Saldo actual B+1440 mediante un único ingreso; anota el saldo posterior.$texto$,$texto$Banco B + $1,440.00; beneficio total $160.00 publicado con los abonos.$texto$,$texto$Validación completa confirmada por el propietario.$texto$,$texto$No cambiar fechas reales para eludir restricciones. Si el pago ya está validado, sólo consultar; no volver a capturar un registro independiente.$texto$,$texto$/admin/catalogos/pagos$texto$),
('cancelar-pago-anticipado-beca',9,$texto$Verificar liquidación, beca y comprobante familiar$texto$,$texto$Administración y tutor$texto$,$texto$Adeudos, Acuerdo, Becas y Portal familiar$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca alumno/ANTICIPO-TEST-02 y selecciona Todos o Liquidado → Aplicar filtros → Ver noviembre → Resumen: Original1000, Descuentos y becas280, Total con ajustes720, Abonos vigentes720 y Falta por pagar0. Repite con diciembre. 2. En Historial de ajustes de cada cargo consulta BECA200 y DESCUENTO80 por acuerdo. En Becas por alumno comprueba20% Activa; en el acuerdo, Beneficio aplicado. 3. En la ventana privada entra a /familias como tutor → selecciona al alumno → Tus pagos; recarga y comprueba que estas mensualidades ya no estén pendientes y el comprobante PDF del pago1440 abra correctamente. 4. Anota las evidencias y el saldo bancario B+1440 antes de cancelar; el propietario confirmó todos estos resultados del nuevo ensayo.$texto$,$texto$Ambos adeudos0, beca20% activa y comprobante del pago1440.$texto$,$texto$Estado anterior a cancelación comprobado.$texto$,$texto$Con saldo pendiente oculta los cargos liquidados; usa Todos o Liquidado. No cancelar hasta identificar inequívocamente el pago de ensayo y su cuenta.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-pago-anticipado-beca',10,$texto$Cancelar el mismo pago registrado por error$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Gestión$texto$,$texto$1. Entra a Administración → Finanzas → Pagos recibidos, busca el MISMO folio validado de1440 → Ver → Gestión → Cancelar pago registrado por error. 2. Captura Motivo obligatorio: Ensayo ANTICIPO-TEST-02: cancelación de pago simulado registrado por error para comprobar reversión del ingreso, abonos y beneficio anticipado, conservando la beca del 20%. 3. Pulsa Cancelar y conservar trazabilidad; en Confirmar cancelación del pago revisa folio, cuenta,1440 y motivo. Cancelar en el modal sólo cierra sin ejecutar; si lo usas, vuelve a abrirlo y conserva los datos. 4. Pulsa Confirmar cancelación una sola vez y espera Pago cancelado con motivo conservado; no crees una devolución ni canceles los adeudos.$texto$,$texto$La cancelación libera abonos, revierte beneficio y compensa el ingreso1440.$texto$,$texto$Registro erróneo cancelado, con trazabilidad.$texto$,$texto$Si el dinero sí se recibió y debe entregarse al tutor, usa Devolución en otro escenario. Pagos con devoluciones ejecutadas o cambios incompatibles bloquean esta operación; no evadir controles. Esta guía no confirma devoluciones anticipadas.$texto$,$texto$/admin/catalogos/pagos$texto$),
('cancelar-pago-anticipado-beca',11,$texto$Comprobar reversas y beca conservada$texto$,$texto$Administración$texto$,$texto$Pagos, Acuerdos, Adeudos, Historial de ajustes y Cuentas$texto$,$texto$1. En Pagos recibidos abre el folio → Gestión y consulta Pago cancelado y motivo. En Convenios de pago → Acuerdos por pago anticipado abre el acuerdo y comprueba Acuerdo cancelado; su tabla conserva la propuesta histórica, no la deuda actual. 2. En Adeudos de alumnos busca alumno/concepto, Con saldo pendiente → Aplicar filtros → Ver de cada mes: total exigible800, abonos vigentes0 y Falta por pagar800. 3. En Historial de ajustes abre Ver de los registros relacionados y Ver cargo para rastrear BECA200 conservada, descuento80 original y reversa que lo deja sin efecto; conserva también las aplicaciones y sus reversas. En Becas por alumno comprueba20% Activa. 4. En Cuentas financieras compara Saldo actual con B: debe restar1440 respecto al saldo anterior a cancelar, conservando el ingreso y su egreso compensatorio. Si hubo otros movimientos, sepáralos de este ensayo.$texto$,$texto$Dos deudas800, beca200 por mes, beneficio reversado y banco B.$texto$,$texto$Reversión administrativa confirmada, sin borrar historia.$texto$,$texto$No reversar manualmente el descuento del acuerdo desde Historial de ajustes ni modificar saldo inicial: la cancelación del pago ya realiza las reversas correspondientes.$texto$,$texto$/admin/catalogos/ajustes-cargo$texto$),
('cancelar-pago-anticipado-beca',12,$texto$Confirmar el regreso de ambas mensualidades al portal$texto$,$texto$Tutor y administración$texto$,$texto$Portal familiar → Tus pagos y cierre de evidencias$texto$,$texto$1. En la ventana privada entra a /familias con el tutor → selecciona al alumno → Tus pagos y recarga después de cancelar. 2. Identifica noviembre y diciembre de ANTICIPO-TEST-02: deben aparecer800 cada uno, deuda total1600; otras deudas permanecen fuera del ensayo. 3. Comprueba que el historial conserva el pago como Cancelado y no ofrece comprobante vigente para ese registro. Guarda folios y evidencias de antes/después sin reportar otra transferencia. 4. Cierra el caso: el propietario confirmó la cancelación y todos los controles, aclarando expresamente que el portal muestra dos cargos800. Ese resultado es correcto:1000-200 de beca=800 por mes; el beneficio80 desaparece al cancelar.$texto$,$texto$Noviembre $800.00 y diciembre $800.00; total $1,600.00.$texto$,$texto$Caso confirmado completo de validación y cancelación.$texto$,$texto$No repetir el caso ya confirmado. Mensualidad bonificada, sustitución de beca, monto fijo, devoluciones y validación desde dos pestañas son escenarios separados todavía pendientes.$texto$,NULL)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;

-- Mantener la guía anterior como caso de validación, enlazando la nueva confirmación separada.
UPDATE guia_proceso_paso SET instrucciones=replace(instrucciones,
 $texto$cancelar o devolver es un escenario separado aún no confirmado$texto$,
 $texto$la cancelación se confirmó en otro ensayo y tiene su propia guía; la devolución sigue pendiente$texto$),
 precaucion=$texto$No aplicar ajuste manual ni cancelar cargo. La cancelación del pago tiene su propia guía confirmada: Pago anticipado y cancelación: dos mensualidades, beca del 20% y beneficio del 10%. Mensualidad gratis, sustitución de beca, monto fijo y devolución siguen pendientes.$texto$
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='pago-anticipado-beca-porcentaje') AND numero=10;
UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-09'
WHERE slug='pago-anticipado-beca-porcentaje';
